create table xxventuri.ds_envelope_callback_log (
    callback_id      number generated by default as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache 20
    noorder nocycle nokeep noscale not null enable,
    event_name       varchar2(100 byte),
    envelope_id      varchar2(100 byte),
    recipient_id     varchar2(50 byte),
    account_id       varchar2(100 byte),
    envelope_status  varchar2(50 byte),
    callback_payload clob,
    received_on      date default sysdate,
    signed_file_name varchar2(255 byte),
    signed_file_blob blob,
    mime_type        varchar2(200 byte),
    charset          varchar2(200 byte),
    document_id      number,
    time             varchar2(250 byte),
    mail_sent_flag   char(1 byte) default 'N'
);

alter table xxventuri.ds_envelope_callback_log add primary key ( callback_id )
    using index enable;


